window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c606de68f60ef1dd"]={"versions": [{"id": "FIG-c606de68f60ef1dd", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Feature Model Exchange Format (TPS Feature Model Exchange Format). Das Diagramm definiert die metamodellierte Struktur der Klasse <code>FMFeatureMap</code> und deren Beziehungsgefüge zu Abbildungselementen, Bedingungen, Zusicherungen und Wertebereichsspezifikationen für Systemkonstanten und Post-Build-Kriterien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>FMFeatureMap</code> («ARElement»): Oberstes Wurzelelement des Feature-Mappings. Enthält per Komposition über die Rolle <code>+mapping</code> mit Multiplizität <code>0..*</code> Instanzen von <code>FMFeatureMapElement</code>.\n</li><li><code>FMFeatureMapElement</code> («Identifiable»): Repräsentiert ein einzelnes Zuordnungselement innerhalb der Map. Es aggregiert bzw. referenziert:\n<ul class=\"fig-list\"><li>Per Komposition über die Rolle <code>+condition</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapCondition</code>.\n</li><li>Per Komposition über die Rolle <code>+assertion</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapAssertion</code>.\n</li><li>Über gerichtete Assoziationen die Ziel-Wertesätze:\n<ul class=\"fig-list\"><li>Rolle <code>+swSystemconstantValueSet</code> mit Multiplizität <code>0..*</code> zu <code>SwSystemconstantValueSet</code> («ARElement»).\n</li><li>Rolle <code>+postBuildVariantCriterionValueSet</code> mit Multiplizität <code>0..*</code> zu <code>PostBuildVariantCriterionValueSet</code> («ARElement»).\n</li></ul>\n</li></ul>\n</li><li><code>FMFeatureMapCondition</code> («Identifiable»): Kapselt eine Vorbedingung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmCond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndAttributes</code> (Typ: <code>FMFormulaByFeaturesAndAttributes</code>).\n</li><li><code>FMFeatureMapAssertion</code> («Identifiable»): Kapselt eine Zusicherung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmSyscond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndSwSystemconsts</code> (Typ: <code>FMFormulaByFeaturesAndSwSystemconsts</code>).\n</li><li><code>SwSystemconstantValueSet</code> («ARElement») und <code>PostBuildVariantCriterionValueSet</code> («ARElement»): Modellieren die externen referenzierbaren Wertesätze.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm des Metamodells definiert das Klassendiagramm keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe. Es legt die syntaktische Struktur und Dekompositionshierarchie für Mappings zwischen Feature-Modellen und Systemkonstanten fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Beziehungen und Multiplizitäten regeln die syntaktische Validität eines AUTOSAR-Feature-Mapping-Modells:</p>\n<ul class=\"fig-list\"><li>Ein <code>FMFeatureMapElement</code> kann ohne Bedingungen oder Zusicherungen definiert werden (<code>0..*</code>), darf jedoch jeweils beliebig viele aufnehmen.\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapCondition</code> muss zwingend genau eine <code>FMConditionByFeaturesAndAttributes</code> enthalten (<code>+fmCond 1</code>).\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapAssertion</code> muss zwingend genau eine <code>FMConditionByFeaturesAndSwSystemconsts</code> enthalten (<code>+fmSyscond 1</code>).\n</li><li>Die Referenzen auf <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind optional und mehrwertig (<code>0..*</code>).\n</li><li><code>FMFeatureMap</code>, <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind als <code>ARElement</code> eigenständig im AUTOSAR-Paketbaum platzierbar, während <code>FMFeatureMapElement</code>, <code>FMFeatureMapCondition</code> und <code>FMFeatureMapAssertion</code> als <code>Identifiable</code> geschachtelte Identifizierbarkeit besitzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b45bb4ffeb64a7d6", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Feature Model Exchange Format (TPS Feature Model Exchange Format). Das Diagramm definiert die metamodellierte Struktur der Klasse <code>FMFeatureMap</code> und deren Beziehungsgefüge zu Abbildungselementen, Bedingungen, Zusicherungen und Wertebereichsspezifikationen für Systemkonstanten und Post-Build-Kriterien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>FMFeatureMap</code> («ARElement»): Oberstes Wurzelelement des Feature-Mappings. Enthält per Komposition über die Rolle <code>+mapping</code> mit Multiplizität <code>0..*</code> Instanzen von <code>FMFeatureMapElement</code>.\n</li><li><code>FMFeatureMapElement</code> («Identifiable»): Repräsentiert ein einzelnes Zuordnungselement innerhalb der Map. Es aggregiert bzw. referenziert:\n<ul class=\"fig-list\"><li>Per Komposition über die Rolle <code>+condition</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapCondition</code>.\n</li><li>Per Komposition über die Rolle <code>+assertion</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapAssertion</code>.\n</li><li>Über gerichtete Assoziationen die Ziel-Wertesätze:\n<ul class=\"fig-list\"><li>Rolle <code>+swSystemconstantValueSet</code> mit Multiplizität <code>0..*</code> zu <code>SwSystemconstantValueSet</code> («ARElement»).\n</li><li>Rolle <code>+postBuildVariantCriterionValueSet</code> mit Multiplizität <code>0..*</code> zu <code>PostBuildVariantCriterionValueSet</code> («ARElement»).\n</li></ul>\n</li></ul>\n</li><li><code>FMFeatureMapCondition</code> («Identifiable»): Kapselt eine Vorbedingung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmCond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndAttributes</code> (Typ: <code>FMFormulaByFeaturesAndAttributes</code>).\n</li><li><code>FMFeatureMapAssertion</code> («Identifiable»): Kapselt eine Zusicherung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmSyscond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndSwSystemconsts</code> (Typ: <code>FMFormulaByFeaturesAndSwSystemconsts</code>).\n</li><li><code>SwSystemconstantValueSet</code> («ARElement») und <code>PostBuildVariantCriterionValueSet</code> («ARElement»): Modellieren die externen referenzierbaren Wertesätze.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm des Metamodells definiert das Klassendiagramm keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe. Es legt die syntaktische Struktur und Dekompositionshierarchie für Mappings zwischen Feature-Modellen und Systemkonstanten fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Beziehungen und Multiplizitäten regeln die syntaktische Validität eines AUTOSAR-Feature-Mapping-Modells:</p>\n<ul class=\"fig-list\"><li>Ein <code>FMFeatureMapElement</code> kann ohne Bedingungen oder Zusicherungen definiert werden (<code>0..*</code>), darf jedoch jeweils beliebig viele aufnehmen.\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapCondition</code> muss zwingend genau eine <code>FMConditionByFeaturesAndAttributes</code> enthalten (<code>+fmCond 1</code>).\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapAssertion</code> muss zwingend genau eine <code>FMConditionByFeaturesAndSwSystemconsts</code> enthalten (<code>+fmSyscond 1</code>).\n</li><li>Die Referenzen auf <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind optional und mehrwertig (<code>0..*</code>).\n</li><li><code>FMFeatureMap</code>, <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind als <code>ARElement</code> eigenständig im AUTOSAR-Paketbaum platzierbar, während <code>FMFeatureMapElement</code>, <code>FMFeatureMapCondition</code> und <code>FMFeatureMapAssertion</code> als <code>Identifiable</code> geschachtelte Identifizierbarkeit besitzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-279187fd7260a8a7", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Feature Model Exchange Format (TPS Feature Model Exchange Format). Das Diagramm definiert die metamodellierte Struktur der Klasse <code>FMFeatureMap</code> und deren Beziehungsgefüge zu Abbildungselementen, Bedingungen, Zusicherungen und Wertebereichsspezifikationen für Systemkonstanten und Post-Build-Kriterien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>FMFeatureMap</code> («ARElement»): Oberstes Wurzelelement des Feature-Mappings. Enthält per Komposition über die Rolle <code>+mapping</code> mit Multiplizität <code>0..*</code> Instanzen von <code>FMFeatureMapElement</code>.\n</li><li><code>FMFeatureMapElement</code> («Identifiable»): Repräsentiert ein einzelnes Zuordnungselement innerhalb der Map. Es aggregiert bzw. referenziert:\n<ul class=\"fig-list\"><li>Per Komposition über die Rolle <code>+condition</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapCondition</code>.\n</li><li>Per Komposition über die Rolle <code>+assertion</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapAssertion</code>.\n</li><li>Über gerichtete Assoziationen die Ziel-Wertesätze:\n<ul class=\"fig-list\"><li>Rolle <code>+swSystemconstantValueSet</code> mit Multiplizität <code>0..*</code> zu <code>SwSystemconstantValueSet</code> («ARElement»).\n</li><li>Rolle <code>+postBuildVariantCriterionValueSet</code> mit Multiplizität <code>0..*</code> zu <code>PostBuildVariantCriterionValueSet</code> («ARElement»).\n</li></ul>\n</li></ul>\n</li><li><code>FMFeatureMapCondition</code> («Identifiable»): Kapselt eine Vorbedingung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmCond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndAttributes</code> (Typ: <code>FMFormulaByFeaturesAndAttributes</code>).\n</li><li><code>FMFeatureMapAssertion</code> («Identifiable»): Kapselt eine Zusicherung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmSyscond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndSwSystemconsts</code> (Typ: <code>FMFormulaByFeaturesAndSwSystemconsts</code>).\n</li><li><code>SwSystemconstantValueSet</code> («ARElement») und <code>PostBuildVariantCriterionValueSet</code> («ARElement»): Modellieren die externen referenzierbaren Wertesätze.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm des Metamodells definiert das Klassendiagramm keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe. Es legt die syntaktische Struktur und Dekompositionshierarchie für Mappings zwischen Feature-Modellen und Systemkonstanten fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Beziehungen und Multiplizitäten regeln die syntaktische Validität eines AUTOSAR-Feature-Mapping-Modells:</p>\n<ul class=\"fig-list\"><li>Ein <code>FMFeatureMapElement</code> kann ohne Bedingungen oder Zusicherungen definiert werden (<code>0..*</code>), darf jedoch jeweils beliebig viele aufnehmen.\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapCondition</code> muss zwingend genau eine <code>FMConditionByFeaturesAndAttributes</code> enthalten (<code>+fmCond 1</code>).\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapAssertion</code> muss zwingend genau eine <code>FMConditionByFeaturesAndSwSystemconsts</code> enthalten (<code>+fmSyscond 1</code>).\n</li><li>Die Referenzen auf <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind optional und mehrwertig (<code>0..*</code>).\n</li><li><code>FMFeatureMap</code>, <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind als <code>ARElement</code> eigenständig im AUTOSAR-Paketbaum platzierbar, während <code>FMFeatureMapElement</code>, <code>FMFeatureMapCondition</code> und <code>FMFeatureMapAssertion</code> als <code>Identifiable</code> geschachtelte Identifizierbarkeit besitzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f6d3466698488871", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Feature Model Exchange Format (TPS Feature Model Exchange Format). Das Diagramm definiert die metamodellierte Struktur der Klasse <code>FMFeatureMap</code> und deren Beziehungsgefüge zu Abbildungselementen, Bedingungen, Zusicherungen und Wertebereichsspezifikationen für Systemkonstanten und Post-Build-Kriterien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>FMFeatureMap</code> («ARElement»): Oberstes Wurzelelement des Feature-Mappings. Enthält per Komposition über die Rolle <code>+mapping</code> mit Multiplizität <code>0..*</code> Instanzen von <code>FMFeatureMapElement</code>.\n</li><li><code>FMFeatureMapElement</code> («Identifiable»): Repräsentiert ein einzelnes Zuordnungselement innerhalb der Map. Es aggregiert bzw. referenziert:\n<ul class=\"fig-list\"><li>Per Komposition über die Rolle <code>+condition</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapCondition</code>.\n</li><li>Per Komposition über die Rolle <code>+assertion</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapAssertion</code>.\n</li><li>Über gerichtete Assoziationen die Ziel-Wertesätze:\n<ul class=\"fig-list\"><li>Rolle <code>+swSystemconstantValueSet</code> mit Multiplizität <code>0..*</code> zu <code>SwSystemconstantValueSet</code> («ARElement»).\n</li><li>Rolle <code>+postBuildVariantCriterionValueSet</code> mit Multiplizität <code>0..*</code> zu <code>PostBuildVariantCriterionValueSet</code> («ARElement»).\n</li></ul>\n</li></ul>\n</li><li><code>FMFeatureMapCondition</code> («Identifiable»): Kapselt eine Vorbedingung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmCond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndAttributes</code> (Typ: <code>FMFormulaByFeaturesAndAttributes</code>).\n</li><li><code>FMFeatureMapAssertion</code> («Identifiable»): Kapselt eine Zusicherung des Mappings. Besitzt eine strikte Kompositionsbeziehung mit Rolle <code>+fmSyscond</code> und Kardinalität <code>1</code> zur Klasse <code>FMConditionByFeaturesAndSwSystemconsts</code> (Typ: <code>FMFormulaByFeaturesAndSwSystemconsts</code>).\n</li><li><code>SwSystemconstantValueSet</code> («ARElement») und <code>PostBuildVariantCriterionValueSet</code> («ARElement»): Modellieren die externen referenzierbaren Wertesätze.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm des Metamodells definiert das Klassendiagramm keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe. Es legt die syntaktische Struktur und Dekompositionshierarchie für Mappings zwischen Feature-Modellen und Systemkonstanten fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Beziehungen und Multiplizitäten regeln die syntaktische Validität eines AUTOSAR-Feature-Mapping-Modells:</p>\n<ul class=\"fig-list\"><li>Ein <code>FMFeatureMapElement</code> kann ohne Bedingungen oder Zusicherungen definiert werden (<code>0..*</code>), darf jedoch jeweils beliebig viele aufnehmen.\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapCondition</code> muss zwingend genau eine <code>FMConditionByFeaturesAndAttributes</code> enthalten (<code>+fmCond 1</code>).\n</li><li>Jede vorhandene Instanz von <code>FMFeatureMapAssertion</code> muss zwingend genau eine <code>FMConditionByFeaturesAndSwSystemconsts</code> enthalten (<code>+fmSyscond 1</code>).\n</li><li>Die Referenzen auf <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind optional und mehrwertig (<code>0..*</code>).\n</li><li><code>FMFeatureMap</code>, <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind als <code>ARElement</code> eigenständig im AUTOSAR-Paketbaum platzierbar, während <code>FMFeatureMapElement</code>, <code>FMFeatureMapCondition</code> und <code>FMFeatureMapAssertion</code> als <code>Identifiable</code> geschachtelte Identifizierbarkeit besitzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-98625214d495ada3", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Feature Model Exchange Format (TPS Feature Model Exchange Format). Das Diagramm definiert die metamodellierte Struktur der Klasse <code>FMFeatureMap</code> und deren Beziehungsgefüge zu Abbildungselementen, Bedingungen, Zusicherungen und Wertebereichsspezifikationen für Systemkonstanten und Post-Build-Kriterien.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Klassen und Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>FMFeatureMap</code> («ARElement»): Oberstes Wurzelelement des Feature-Mappings. Enthält per Komposition über die Rolle <code>+mapping</code> mit Multiplizität <code>0..*</code> Instanzen von <code>FMFeatureMapElement</code>.\n</li><li><code>FMFeatureMapElement</code> («Identifiable»): Repräsentiert ein einzelnes Zuordnungselement innerhalb der Map. Es aggregiert bzw. referenziert:\n<ul class=\"fig-list\"><li>Per Komposition über die Rolle <code>+condition</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapCondition</code>.\n</li><li>Per Komposition über die Rolle <code>+assertion</code> mit Multiplizität <code>0..*</code> Elemente vom Typ <code>FMFeatureMapAssertion</code>.\n</li><li>Über gerichtete Assoziationen die Ziel-Wertesätze:\n<ul class=\"fig-list\"><li>Rolle <code>+swSystemconstantValueSet</code> mit Multiplizität <code>0..*</code> zu <code>SwSystemconstantValueSet</code> («ARElement»).\n</li><li>Rolle <code>+postBuildVariantCriterionValueSet</code> mit Multiplizität <code>0..*</code> zu <code>PostBuildVariantCriterionValueSet</code> («ARElement»).\n</li></ul>\n</li></ul>\n</li><li><code>FMFeatureMapCondition</code> («Identifiable»): Kapselt eine Vorbedingung des Mappings. Besitzt eine optionale Kompositionsbeziehung mit Rolle <code>+fmCond</code> und Kardinalität <code>0..1</code> zur Klasse <code>FMConditionByFeaturesAndAttributes</code> (Typ: <code>FMFormulaByFeaturesAndAttributes</code>).\n</li><li><code>FMFeatureMapAssertion</code> («Identifiable»): Kapselt eine Zusicherung des Mappings. Besitzt eine optionale Kompositionsbeziehung mit Rolle <code>+fmSyscond</code> und Kardinalität <code>0..1</code> zur Klasse <code>FMConditionByFeaturesAndSwSystemconsts</code> (Typ: <code>FMFormulaByFeaturesAndSwSystemconsts</code>).\n</li><li><code>SwSystemconstantValueSet</code> («ARElement») und <code>PostBuildVariantCriterionValueSet</code> («ARElement»): Modellieren die externen referenzierbaren Wertesätze.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Strukturdiagramm des Metamodells definiert das Klassendiagramm keine dynamischen Interaktionen, Nachrichtenaustausche oder zeitlichen Abläufe. Es legt die syntaktische Struktur und Dekompositionshierarchie für Mappings zwischen Feature-Modellen und Systemkonstanten fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Beziehungen und Multiplizitäten regeln die syntaktische Validität eines AUTOSAR-Feature-Mapping-Modells:</p>\n<ul class=\"fig-list\"><li>Ein <code>FMFeatureMapElement</code> kann ohne Bedingungen oder Zusicherungen definiert werden (<code>0..*</code>), darf jedoch jeweils beliebig viele aufnehmen.\n</li><li>Instanzen von <code>FMFeatureMapCondition</code> können optional höchstens eine <code>FMConditionByFeaturesAndAttributes</code> enthalten (<code>+fmCond 0..1</code>).\n</li><li>Instanzen von <code>FMFeatureMapAssertion</code> können optional höchstens eine <code>FMConditionByFeaturesAndSwSystemconsts</code> enthalten (<code>+fmSyscond 0..1</code>).\n</li><li>Die Referenzen auf <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind optional und mehrwertig (<code>0..*</code>).\n</li><li><code>FMFeatureMap</code>, <code>SwSystemconstantValueSet</code> und <code>PostBuildVariantCriterionValueSet</code> sind als <code>ARElement</code> eigenständig im AUTOSAR-Paketbaum platzierbar, während <code>FMFeatureMapElement</code>, <code>FMFeatureMapCondition</code> und <code>FMFeatureMapAssertion</code> als <code>Identifiable</code> geschachtelte Identifizierbarkeit besitzen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c606de68f60ef1dd", "to": "FIG-b45bb4ffeb64a7d6", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b45bb4ffeb64a7d6", "to": "FIG-279187fd7260a8a7", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-279187fd7260a8a7", "to": "FIG-f6d3466698488871", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f6d3466698488871", "to": "FIG-98625214d495ada3", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kompositionsrolle <code>+fmCond</code> von <code>FMFeatureMapCondition</code> zu <code>FMConditionByFeaturesAndAttributes</code>: Multiplizität von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li>Kompositionsrolle <code>+fmSyscond</code> von <code>FMFeatureMapAssertion</code> zu <code>FMConditionByFeaturesAndSwSystemconsts</code>: Multiplizität von <code>1</code> auf <code>0..1</code> gelockert.\n</li></ul>"}]};
